def values(self, *keys):
    # Check if the keys parameter is empty and set it to None if so
    if not keys:
        keys = None
    return [self.data[key] for key in keys] if keys else list(self.data.values())

def data(self, *keys):
    result = {}
    for key in keys:
        if isinstance(key, int):
            if key < 0 or key >= len(self):
                raise IndexError("Index out of bounds")
            result[key] = self[key]
        elif isinstance(key, str):
            if key in self:
                result[key] = self[key]
            else:
                result[key] = None
        else:
            raise TypeError("Key must be an int or str")
    return result

def discard(self, n=-1, qid=-1, dehydration_hooks=None,
                hydration_hooks=None, **handlers):
    if n == -1:
        records = self.output_queue
    else:
        records = self.output_queue[-n:]

    if qid != -1:
        records = [record for record in records if record['qid'] == qid]

    if dehydration_hooks:
        for record in records:
            self._apply_hooks(record, dehydration_hooks)

    if hydration_hooks:
        for record in records:
            self._apply_hooks(record, hydration_hooks)

    output = self._build_response(records, handlers)
    return output

