from functools import wraps
import time

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """

    cache = {}
    last_accessed = {}

    def memoize(f):
        @wraps(f)
        def wrapper(*args, **kwargs):
            key = (hash(args), hash(tup(kwargs.items())))
            if key in cache:
                access_time = last_accessed[key]
                if access_time + ttl < timer():
                    # Expire the cache
                    del cache[key]
                else:
                    # It still within the TTL, so get the results
                    return cache[key]
            # Not in cache or already expired, calculate and cache the results
            value = f(*args, **kwargs)
            cache[key] = value
            last_accessed[key] = timer()
            if len(cache) > maxsize:
                # Remove the least recently accessed item
                least_accessed_key = min(last_accessed, key=last_accessed.get)
                del cache[least_accessed_key]
                del last_accessed[least_accessed_key]
            return value
        return wrapper
    return memoize

class LFUCache:
    def __init__(self, maxsize=128, typed=False):
        self.cache = {}
        self.usage_count = {}
        self.min_increase = 1
        self.typed = typed

        if maxsize > 0:
            self.allocation_optimization = self.LFUCacheAllocationOptimization128perType
        else:
            self.allocation_optimization = self.LFUCacheAllocationOptimization0perType

    def LFUCacheAllocationOptimization128perType(self, key, last_item, last_count, use_list_each_count_type):
        return None

    def LFUCacheAllocationOptimization0perType(self, key, last_item, last_count, use_list_each_count_type):
        return None

    def find_key(self, key):
        return self.cache.get(key)

    def find_last_item(self, key):
        return self.usage_count.get(key, -1)

    def increase_count(self, key, use_list_each_count_type):
        current_count = self.get_current_count(key) + 1
        self.usage_count[key] = current_count

        if self.typed:  # make sure we only look at the same type of key
            k, v = key, self.cache[key]
            if current_count > 2:
                for k1, v1 in self.usage_count.items():
                    if k1 != key and v1 == current_count and v1 == v:
                        self.usage_count[k1] -= 1
                        break
        else:  # we handle the last usage count of all keys
            key = key[0]

        if use_list_each_count_type:
            if key not in self.usage_count:
                self.usage_list[key] = [1]  # Use a list to keep count for different item types
                return 1
            else:
                for count in self.usage_list[key]:
                    if count == current_count:
                        return count
                    elif count < current_count:
                        self.usage_list[key].insert(0, current_count)
                        return current_count
        else:
            return current_count

    def get_item(self, key, use_list_each_count_type):
        if key is None or key == '':
            raise ValueError("key can't be None or an empty string.")
        item = self.find_key(key)
        if item is None:
            raise KeyError("Key not found.")

        last_item = self.find_last_item(key)
        if last_item == -1:
            self.usage_count[key] = 1
        else:
            last_item += 1

        self.usage_count[key] = last_item

        # Handle LRU usage
        self.remove_least_recent_item(use_list_each_count_type)

        return item

    def remove_least_recent_item(self, use_list_each_count_type):
        min_increase = self.min_increase
        min_count = float('inf')
        item_to_remove = None
        for k, v in self.usage_count.items():
            if use_list_each_count_type:
                current_count_list = self.usage_list[k]
                if min_count > current_count_list[0]:
                    min_count = current_count_list[0]
                    item_to_remove = k
            else:
                if min_count > v:
                    min_count = v
                    item_to_remove = k
        if item_to_remove:
            if use_list_each_count_type:
                self.usage_list[item_to_remove].pop(0)
            else:
                self.usage_count.pop(item_to_remove)
            self.cache.pop(item_to_remove)

