def extostr(e, max_level=30, max_path_level=5):
    if not isinstance(e, Exception):
        return "Invalid input: Expected an exception instance."

    def stack_trace(level):
        if level >= max_level:
            return ""
        frame = e.__traceback__.tb_frames[level]
        line = frame.f_lineno
        path = frame.f_code.co_filename if frame.f_code else ""
        return f"  File {path}, line {line}"

    def path_trace(level):
        if level >= max_path_level:
            return ""
        frame = e.__traceback__.tb_frames[level]
        return f"  {frame.f_code.co_name}"

    trace = []
    while e.__traceback__:
        trace.append((stack_trace(len(trace)), path_trace(len(trace))))
        e = e.__traceback__

    return "\n".join(trace)

def append_text_to_file(file_name, text_buffer, encoding, overwrite=False):
    try:
        if overwrite:
            with open(file_name, 'w', encoding=encoding) as file:
                file.write(text_buffer)
                return len(text_buffer.encode(encoding))
        else:
            with open(file_name, 'a', encoding=encoding) as file:
                file.write(text_buffer)
                return len(text_buffer.encode(encoding))
    except FileNotFoundError:
        try:
            with open(file_name, 'w', encoding=encoding) as file:
                file.write(text_buffer)
                return len(text_buffer.encode(encoding))
        except IOError as e:
