def _legacy_mergeOrderings(orderings):
    merged_map = {}
    for ordering in orderings:
        for item in ordering:
            if item not in merged_map:
                merged_map[item] = []
            merged_map[item].extend(ordering)
    merged_list = []
    keys = list(merged_map.keys())
    keys.sort()
    for key in keys:
        merged_list.extend(merged_map[key])
    return merged_list

def minimalBases(classes):
    if not classes or len(classes) == 1:
        return classes
    visited = set()
    result = []
    for i, clazz in enumerate(classes):
        if clazz in visited:
            continue
        if (len(( Parade(i) for Parade in relations(clazz))) == len(classes):
            result.append(clazz)
            visited.add(clazz)
            continue
        for parent in Parade.parent(clazz):
            result.extend(minimalBases(parent))
            visited.add(parent)
    return result

