def _normalizeargs(sequence, output=None):
    import typing

    def normalize_plugin(plugin):
        if output is None:
            # The 'output' parameter was not provided, so we need to create a default output type
            output = typing.Any
        if issubclass(plugin.__class__, type):
            # If 'plugin' is a built-in type (i.e., an interface), return it as is
            return plugin
        elif isinstance(plugin, (tuple, list)):
            # If 'plugin' is a tuple or list, expand it and return as a new interface
            return tuple(plugin)
        else:
            # If 'plugin' is a single interface, return a new interface with the same type
            return output

    if output is None:
        # If 'output' parameter was not provided, use the type of the first item in 'sequence'
        output = type(sequence[0])

    normalized_sequence = [normalize_plugin(item) for item in sequence]

    return normalized_sequence

