import collections

 def _update_context(self, context):
    """Update *context* with the properties of this graph.

    *context.error* is appended with indices of errors.
    Example subcontext for a graph with fields "E,t,error_E_low":
        {"error": {"x_low": {"index": 2}}}.
    Note that error names are called "x", "y" and "z"
    (this corresponds to first three coordinates,
    if they are present), which allows to simplify plotting.
    Existing values are not removed
    from *context.value* and its subcontexts.

    Called on "destruction" of the graph (for example,
    in :class:`.ToCSV`). By destruction we mean conversion
    to another structure (like text) in the flow.
    The graph object is not really destroyed in this process.
    """

    # Check if the context is None or not a dictionary
    if context is None or not isinstance(context, dict):
        raise ValueError("Context must be a dictionary")

    # Check if the 'value' key exists in the context
    if 'value' not in context:
        context['value'] = {}

    # Iterate over the graph fields and update the context
    for field, value in self.graph_fields.items():
        if isinstance(value, tuple):
            # Calculate ranges based on value type
            if isinstance(value, int):
                range_start = -10
                range_end = 10
            elif isinstance(value, float):
                range_start = -10.0
                range_end = 10.0
            # Append to context.error with various indices
            for index in range(range_start, range_end + 1):
                context['error'][field] = {"index": index}
        else:
            # Update existing value
            if field in context['value']:
                context['value'][field].append(value)
            else:
                context['value'][field] = [value]

    # Update error index for each field
    for field, values in context.items():
        if field != 'value' and isinstance(values, list):
            for index, value in enumerate(values):
                if isinstance(value, float) and value < 0:
                    context[field][index]['index'] -= 1
    return context

