def difference(d1, d2, level=-1):
    if not isinstance(d1, dict) or not isinstance(d2, dict):
        raise ValueError("Both inputs must be dictionaries.")

    if level == -1:
        return {k: v for k, v in d1.items() if k not in d2}
    else:
        if level == 0:
            return {k: d1[k] for k in d1 if k not in d2}
        else:
            diff = {}
            for k, v in d1.items():
                if k in d2:
                    if isinstance(v, dict) and isinstance(d2[k], dict):
                        diff[k] = difference(v, d2[k], level - 1)
                    elif v != d2[k]:
                        diff[k] = v
                else:
                    diff[k] = v
            return diff

