    last_applied_manifest_dict = {
        field['field_name'] if 'field_name' in field else field['name']: 
        field.get('initial_value', default_value(field['default_value']) if 'default_value' in field else None
        for field in observer_schema
    }

    for obj in response:
        for field_name, value in obj.items():
            if field_name in last_applied_manifest:
                continue
            field = next((f for f in observer_schema if f['name'] == field_name), None)
            if not field:
                continue
            if not field.get('initial_value', None) and field.get('default_value', None):
                value = default_value(field['default_value'])
            last_applied_manifest_dict[field_name] = value

    return list(last_applied_manifest_dict.values())

