def format(self, sql: AnyStr, params: Union[Dict[Union[str, int], Any], Sequence[Any]]):
    if not isinstance(sql, (str, bytes)):
        raise TypeError("sql must be a string or bytes")
    if not isinstance(params, (dict, list)) or isinstance(params, str):
        raise TypeError("params must be a mapping or a list")
    if self.SQLParams.in_style == 'named':
        if not isinstance(params, dict):
            raise TypeError("params must be a dictionary")
        for key, val in params.items():
            if not issubclass(type(val), self.SQLParams.param_type):
                raise TypeError(f"param type for '{key}' is {type(val)}, expected {self.SQLParams.param_type}")
    elif self.SQLParams.in_style == 'ordinal':
        if not isinstance(params, list):
            raise TypeError("params must be a list")
        for i in range(len(params)):
            if isinstance(params[i], tuple) and len(params[i]) != 2:
                raise TypeError(f"invalid tuple length for param at index {i}")
    else:
        raise ValueError("Invalid SQLParams.in_style")
    return sql, params

