def validate(self, inventory, extract_spec_version=False):
    # Check if the inventory dictionary is not empty
    if not isinstance(inventory, dict) or not inventory:
        raise ValueError("Inventory dictionary cannot be empty")

    # Extract the specification version based on extract_spec_version parameter
    if extract_spec_version:
        if 'type' not in inventory:
            raise ValueError("Type value is missing in the inventory dictionary")
        type_value = inventory['type']
        if type_value not in self.spec_version:
            raise ValueError(f"Type '{type_value}' is not in the valid version list")
    else:
        # Get the specification version from the dictionary if it exists
        version = inventory.get('version', self.spec_version)
        if version not in self.spec_version:
            raise ValueError(f"Spec version '{version}' is not in the valid version list")

    # Get the minimum and maximum values
    min_val = inventory.get('min', None)
    max_val = inventory.get('max', None)

    # Validate the keys of the dictionary
    if inventory and not isinstance(inventory, dict):
        raise ValueError("Inventory dictionary should be a dictionary")

    # Process each item based on the specification version
    for key, value in inventory.items():
        # Convert value to string for processing
        try:
            value_str = str(value)
        except TypeError:
            # If value is not a string, attempt to convert it
            try:
                value_str = str(float(value))
            except ValueError:
                raise TypeError(f"Value for key '{key}' cannot be converted to string")

        # Check if the value is within the specified range
        if min_val is not None:
            if not (min_val <= float(value_str) <= max_val):
                raise ValueError(f"Value for key '{key}' is out of range")

