import zipfile

def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.
    """
    if not zipfile.is_zipfile(zip_path) or not zip_path:
        raise ValueError("Input path must be a valid zip file.")

    with zipfile.ZipFile(zip_path) as zip_ref:
        files = {
            file: zip_ref.extractfile(file).read() for file in zip_ref.namelist() if file.endswith('.xml')
        }

    return files

def fix_namespace_prefix_w(content):
    if not isinstance(content, str):
        raise TypeError("Content must be a string")

    processed_contents = []
    prefixes = {'w:st="': 'w-st="'}

    for item in content.split('\n'):
        for old_prefix, new_prefix in prefixes.items():
            item = item.replace(old_prefix, new_prefix)
        processed_contents.append(item)

    return '\n'.join(processed_contents)

