def _extract_number_and_suppl_from_issue_element(issue):
    patent_numbers = []
    supplement_substrings = re.findall(r'(\d+(\s*Suppl|\s+)?)', issue)

    for substring in supplement_substrings:
        if substring.strip('-'):
            part = re.split(r'\s+', substring.strip())
            if part[0].isdigit():
                patent_numbers.append(int(part[0]))
            if 'Suppl' in part:
                input_param = part[0] + ' suppl'
                patent_numbers.append(int(input_param))

    return patent_numbers

