def absorb(self, args):
    if not args:
        return []

    absorbed_args = []
    current_expr = args[0]

    for expr in args[1:]:
        if expr == current_expr:
            absorbed_args.append(expr)
        elif (expr & current_expr | ~expr & current_expr) == expr:
            absorbed_args.append(expr)

    return absorbed_args

def on(self, hook):
    from functools import wraps

    def decorator(func):
        with self._registry_lock:
            if hook in self._handlers:
                self._handlers[hook].append(func)
            else:
                self._handlers[hook] = [func]
        return func

    return decorator

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    try:
        # Python 2 implementation of tzname()
        return namefunc()
    except TypeError as e:
        # Handle case where namefunc does not return a string
        return str(namefunc())
    except Exception as e:
        # Handle any other exceptions that might occur
        return "Error: " + str(e)

