def deep_merge_nodes(nodes: List[Tuple[any, any]]) -> List[Tuple[any, any]]:
    merged_nodes = []
    already_visited = set()

    def merge(orig_map, override_map):
        """Helper function to merge two mapping nodes."""
        for key in override_map:
            if key in orig_map:
                if isinstance(orig_map[key], MappingNode) and isinstance(override_map[key], MappingNode):
                    merge(orig_map[key], override_map[key])
                else:
                    # Override non-MappingNode values with last occurrence
                    merged_nodes.append((key, override_map[key]))
            else:
                merged_nodes.append((key, override_map[key]))

    def handle_node(node):
        """Helper function to handle a single node."""
        if isinstance(node, ScalarNode):
            # Leaf node, directly append to the result
            merged_nodes.append(node)
        elif isinstance(node, MappingNode):
            # Map node, recursively merge and add to result
            if node.tag == 'tag:yaml.org,2002:map':
                key = node.value
                if key in already_visited:
                    # Duplicate node, use last occurrence
                    merged_nodes.append((key, node))
                else:
                    # New node, merge and add to result
                    merged_nodes.append((key,	node))
                    already_visited.add(key)
                    merge(node.value, {})
            else:
                # Other types, append directly
                merged_nodes.append(node)

    # Process nodes
    for key, value in nodes:
        handle_node(value)

    return merged_nodes

