from typing import List, Tuple, Union

class ConfigurationNode:
    def __init__(self, tag: str, value: Union[str, int, None]):
        self.tag = tag
        self.value = value

def deep_merge_nodes(nodes: List[Tuple[ConfigurationNode, ConfigurationNode]]) -> List[Tuple[ConfigurationNode, ConfigurationNode]]:
    merged_nodes = {}
    for node1, node2 in nodes:
        if node1.tag in merged_nodes:
            if not isinstance(merged_nodes[node1.tag], MappingNode):
                merged_nodes[node1.tag] = ConfigurationNode(node1.tag, node1.value)
            if isinstance(node2.value, MappingNode):
                deep_merge_nodes([(node1.tag, ConfigurationNode(node1.tag, merged_nodes[node1.tag].value)), (node1.tag, ConfigurationNode(node1.tag, node2.value))])
            else:
                merged_nodes[node1.tag].value = node2.value
        else:
            merged_nodes[node1.tag] = node2

    return [(key, ConfigurationNode(value.tag, value.value)) for key, value in merged_nodes.items()]

