def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    import re

    # Regular expression to match human-readable file size
    pattern = re.compile(
        r"^(\d+(?:\.\d+)?)(K|M|G|T)$",
        re.IGNORECASE | re.MULTILINE,
    )

    match = pattern.match(size)
    if match:
        amount = float(match.group(1))
        unit = match.group(2)
        if unit.upper() == "K":
            return int(amount * 1024)
        elif unit.upper() == "M":
            return int(amount * 1024 ** 2)
        elif unit.upper() == "G":
            return int(amount * 1024 ** 3)
        elif unit.upper() == "T":
            return int(amount * 1024 ** 4)
    return None

def _dictsum(dicts):
    result = {}
    for d in dicts:
        for key, value in d.items():
            if key in result:
                result[key] += value
            else:
                result[key] = value
    return result

def _replace_url_args(url, url_args):
    import re

    if not isinstance(url, str) or not isinstance(url_args, dict):
        raise ValueError("URL and URL arguments must be strings and dictionaries, respectively.")

    for key, value in url_args.items():
        if not isinstance(value, (int, str)):
            raise TypeError("URL arguments must be integer or string values.")

        pattern = re.compile(r'@\' + re.escape(key) + r'\'')

        # Replace the url string with the corresponding value in url_args
        url = pattern.sub(str(value), url)

    return url

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    if not alphabet or not alphabet:  # Handle empty or null input
        raise ValueError("Both alphabet and padding must not be null")

    # Convert the number from base 10 to the chosen alphabet
    digits = []
    while number > 0:
        digits.insert(0, alphabet[number % len(alphabet)])
        number //= len(alphabet)

    # Pad the result if necessary
    if padding is not None and len(digits) < padding:
        digits.extend(['0'] * (padding - len(digits)))

    # Join digits to form the final string
    return ''.join(digits)

