def string_to_int(string: str, alphabet: List[str]) -> int:
    if not string:
        return 0

    max_value = 0
    for char in string:
        if char not in alphabet:
            raise ValueError(f"Invalid character in the string: {char}")

        max_value = max(max_value, alphabet.index(char))

    return max_value

def regex_dict(item):
    """
    Convert *.cpp keys to regex keys

    Given a dict where the keys are all filenames with wildcards, convert only
    the keys into equivalent regexes and leave the values intact.

    Example:

    rules = {
        '*.cpp':
            {'a': 'arf', 'b': 'bark', 'c': 'coo'},
        '*.h':
            {'h': 'help'}
    }
    regex_keys = regex_dict(rules)

    Args:
        item: dict to convert
    Returns:
        dict with keys converted to regexes
    """
    regex_keys = {}
    for key, value in item.items():
        if key.endswith('.cpp'):
            new_key = re.compile(key.replace('.', '.*'))
            regex_keys[new_key] = value
        else:
            regex_keys[key] = value
    return regex_keys

import re

def unquote(name):
    """Remove quote from the given name."""
    if not re.match(r"^[^'\""]+$", name):
        raise ValueError("Input name should not contain quotes.")

    # Remove the first and last character if they are quotes
    if name[0] == name[-1] and name[0] in ('"', "'"):
        name = name[1:-1]

    return name

import re

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if platform == 'this':
        platform = os.name.lower()
    elif platform == 1:
        platform = 'posix'
    elif platform == 0:
        platform = 'cmd'
    else:
        raise ValueError("Invalid platform value. Use 'this', 1, or 0.")

    if platform == 'posix':
        return re.split('\s+', s)
    elif platform == 'cmd':
        return re.split(' ', s)
    else:
        raise ValueError("Unsupported platform.")

def parse_frequency(frequency):
    if frequency is None or frequency.lower() == "always":
        return None

    try:
        number, unit = map(int, frequency.split())
    except ValueError:
        raise ValueError("Invalid frequency format")

    if unit == "weeks":
        return datetime.timedelta(weeks=number)
    elif unit == "days":
        return datetime.timedelta(days=number)
    elif unit == "hours":
        return datetime.timedelta(hours=number)
    elif unit == "minutes":
        return datetime.timedelta(minutes=number)
    elif unit == "seconds":
        return datetime.timedelta(seconds=number)
    else:
        raise ValueError("Unsupported unit in frequency")

import socket


def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    try:
        if isinstance(host, str) and isinstance(socket.gethostbyname(host), str):
            return host == socket.gethostbyname('localhost')
        elif isinstance(host, int) and socket.gethost_byaddr(host) == '127.0.0.1':
            return True
        else:
            return False
    except Exception as e:
        print(f"Error checking host.Lost connection to host.")
        return False

