def _resolve_string(matcher):
    # Check if matcher has 'name' key required for environment variable lookup
    if 'name' not in matcher:
        raise ValueError("Matcher must contain a 'name' key for environment variable lookup")

    # Construct the environment variable name from the matcher
    env_var_name = matcher['name']

    # Attempt to retrieve the environment variable value
    try:
        # If a 'default' key is provided, use it as the fallback value
        if 'default' in matcher and matcher['default'] is not None:
            return os.getenv(env_var_name, matcher['default'])
        else:
            return os.getenv(env_var_name)
    except KeyError:
        # If the environment variable is not defined and no default is provided, raise an error
        if 'default' in matcher and matcher['default'] is not None:
            return matcher['default']
        else:
            raise ValueError(f"Environment variable '{env_var_name}' is not defined")

