from typing import Set, Optional
from rdflib import Graph, URIRef

def find_roots(
    graph: Graph, prop: URIRef, roots: Optional[Set["Node"]] = None
) -> Set["Node"]:
    if not isinstance(graph, Graph) or not isinstance(prop, URIRef):
        raise TypeError("graph must be a Graph and prop must be a URIRef")

    if roots is None:
        roots = set()

    visited = set()

    def dfs(node):
        if node in visited:
            return
        visited.add(node)
        for child in graph.objects(node, prop):
            dfs(child)

    for node in graph.subjects():
        if not node in visited:
            dfs(node)

    return roots

def _dump_string(obj, dumper=None):
    import yaml

    def _escape(s):
        if s in ("'", '"', '\n', '\r', '\\'):
            return "\\" + s
        return s

    def _escape_seq(seq):
        return "[" + ", ".join(_escape(s) if isinstance(s, str) else str(s) for s in seq) + "]"

    def _escape_map(map):
        return "{" + ", ".join([f"'{key}': {_escape_val(val)}" for key, val in map.items()]) + "}"

    def _escape_val(val):
        if isinstance(val, str):
            return _escape(val)
        elif isinstance(val, (list, tuple)):
            return _escape_seq(val)
        elif isinstance(val, dict):
            return _escape_map(val)
        else:
            return str(val)

    if dumper is None:
        dumper = yaml.Dumper

    return dumper.representers.text_type(_escape_val(obj))

