from zope.interface import Invalid, implementer, provider
from zope.interface.interfaces import Interface

def _verify(iface, candidate, tentative=False, vtype=None):
    errors = []

    try:
        if not tentative:
            if not iface.providedBy(candidate):
                errors.append(Invalid(candidate, "does not provide the interface"))
    except Exception as e:
        errors.append(Invalid(candidate, str(e)))

    if not candidate.implementedBy(type(candidate)):
        errors.append(Invalid(candidate, "does not implement the interface"))

    if not candidate.complexInterfaceProvidedFor(iface):
        errors.append(Invalid(candidate, "does not provide the full interface"))

    if vtype:
        if not all(getattr(candidate, attr, None) is not None for attr in dir(vtype)):
            errors.append(Invalid(candidate, f"does not have all methods of type {vtype.__name__}"))

    if errors:
        raise Invalid(errors)

def verifyObject(iface, candidate, tentative=False):
    try:
        provided =andidate.providedBy if not tentative else False
    except AttributeError:
        if tentative and providedBy is not None:
            return False
        else:
            raise AttributeError(f"Cannot get `providedBy` attribute from {candidate}")

    if not provided:
        allowed_implementers = []
        allowed_providers = []

        if iface.interface_name:
            allowed_implementers.append(iface.interface_name)
            allowed_providers.append(iface.interface_name)

        for cls in candidate.__bases__:
            if hasattr(cls, 'implements'):
                allowed_implementers.append(cls.name)
                if hasattr(cls, 'provider'):
                    allowed_providers.append(cls.name)

        if iface.interface_name in allowed_implementers and iface.interface_name in allowed_providers:
            implemented = interface.providedBy(candidate)
            if implemented:
                return True
        else:
            return False

    # Evaluate methods and attributes
    method_errors = []
    for method_name, method in iface.getMethods(True).items():
        if not hasattr(candidate, method_name):
            method_errors.append(f"'{candidate.__class__.__name__}' does not have method '{method_name}'")

        method_signature = method.signature()
        candidate_signature = candidate.__getattribute__(method_name).__signature__
        if method_signature != candidate_signature and not method.skipped:
            method_errors.append(f"'{candidate.__class__.__name__}' method '{method_name}' does not have the same signature as '{iface.interface_name}' method '{method_name}'")

    attribute_errors = []
    for attr_name, attr on iface.getAttributes(True).items():
        if not hasattr(candidate, attr_name):
            attribute_errors.append(f"'{candidate.__class__.__name__}' does not have attribute '{attr_name}'")

    if method_errors or attribute_errors:
        if len(method_errors) == 1 and len(attribute_errors) == 0:
            raise exception(method_errors[0])
        else:
            raise Exception(f"Errors: {'; '.join(method_errors + attribute_errors)}")
    else:
        return True

def verifyClass(iface, candidate, tentative=False):
    if not iface or not candidate or not isinstance(iface, type) or not isinstance(candidate, type):
        raise ValueError("Invalid input types")

    if tentative:
        return isinstance(candidate, iface)
    else:
        try:
            return isinstance(candidate, iface)
        except Exception as e:
            raise ValueError("Failed to verify class", e)

