from collections import Counter

class LRU:
    def __init__(self):
        self.item_count = Counter()
        self.items = []

    def popitem(self):
        if not self.items:
            raise Exception("LRU cache is empty")

        key, value = self.items.pop(0)
        self.item_count[key] -= 1

        if self.item_count[key] == 0:
            del self.item_count[key]
            del self.items[self.item_count[key]]
            if not self.items:
                raise Exception("LRU cache is empty after removing the last item")

        return key, value

def popitem(self):
    if len(self.cache) == 0:
        raise KeyError('Cache is empty')
    key, value = self.cache.popitem(last=False)
    return key, value

def popitem(self):
    """Remove and return the `(key, value)` pair most recently used."""
    if self._tail is None:
        raise KeyError("popitem from empty deque")
    key = self._tail.key
    if self._tail.prev is None:
        self._head = self._tail = None  # both None if deque empty
    else:
        self._tail = self._tail.prev
        self._tail.next = None
    return key, self._tail.value

import datetime
from dateutil.parser import parser, ParserError
from dateutil.tz import gettz
from dateutil.tzfunctions import gettzinfo, timedelta

class Parser:
    @staticmethod
    def parse(timestr: str, default=None, ignoretz: bool = False, tzinfos: dict = None,
             **kwargs) -> tuple[datetime.datetime | None, tuple[int, str, str] | None]:
        if not isinstance(timestr, str):
            raise TypeError("Input must be a string.")

        try:
            dt: datetime.datetime = parser(timestr, **kwargs)
            if ignoretz:
                dt = dt.replace(tzinfo=None)
            return dt, None
        except ParserError as e:
            raise ParserError from e
        except Exception as e:
            if isinstance(tzinfos, dict) and isinstance(tzinfos['default_tzinfos'], dict):
                default_tzinfo = tzinfos['default_tzinfos'][timestr]
            else:
                default_tzinfo = None
            tzoffsets = {t: tzinfos[t] if t in tzinfos else timedelta(0) for t in dt.tzinfo.aliases}
            tzids = {}
            for t, tzinfo in tzoffsets.items():
                if isinstance(tzinfo, timedelta):
                    tzids[t] = tzinfo.total_seconds() // 3600
                else:
                    tzids[t] = tzinfo
            return None, (datetime.datetime.now(), "date_parse_error", str(e), tzids, default_tzinfo)

def fromutc(self, dt):
    # Normalized case where the dt has both a timezone and a floating point precision
    if dt.tzinfo and dt.microsecond == 0:
        dt += pytz.timedelta(seconds=(dt.tzinfo.utcoffset(dt).total_seconds() // 60 // 60))
        dt = dt.replace(tzinfo=pytz.utc)
        return dt
    # For other cases, we assume dt is already timezone-aware and does not have a floating point precision
    else:
        return dt.astimezone(pytz.utc)

