import requests

class RequestType:
    PUBLIC_MESSAGE = 0
    PRIVATE_MESSAGE = 1
    LEGACY_PAYLOAD = 2

def identify_request(request: RequestType):
    try:
        # Try first public message
        if request == RequestType.PUBLIC_MESSAGE:
            response = requests.get('https://api.diaspora.org/v0/public_messages/1')
            if response.status_code == 200:
                return request
        # Then private message
        if request == RequestType.PRIVATE_MESSAGE:
            response = requests.get('https://api.diaspora.org/v0/private_messages/1')
            if response.status_code == 200:
                return request
        # Check if this is a legacy payload
        if request == RequestType.LEGACY_PAYLOAD:
            payload = {'legacy': True}
            response = requests.post('https://api.diaspora.org/v0/messages', json=payload)
            if response.status_code == 200 and 'legacy' in response.json():
                return request
        return None
    except Exception as e:
        print("An error occurred:", e)
        return None

def format_dt(dt):
    if not dt:
