    correct_format = "%Y-%m-%d %H:%M:%S"  # Replace with the correct datetime format
    if dt.strftime(correct_format) != dt:
        raise ValueError("Incorrect datetime format")

    # Format the datetime as required by D* nodes
    formatted_dt = dt.strftime('%Y-%m-%d %H:%M:%S')

    return formatted_dt

from typing import Tuple, Set

def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    """Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """
    tags = set()
    in_code = False
    replaced_text = ""

    for char in text:
        if char == '\n':
            in_code = False

        if char == '`':
            in_code = not in_code

        if not in_code:
            if char == '[':
                start = text.index(']', index)
                tag = text[start:index + 1]
                tags.add(tag)
                if replacer:
                    replaced_text += replacer(tag)
                else:
                    replaced_text += tag
            elif char == '(':
                start = text.index(')', index)
                tag = text[start:index + 1]
                tags.add(tag)
                if replacer:
                    replaced_text += replacer(tag)
                else:
                    replaced_text += tag
            elif char == '{':
                start = text.index('}', index)
                tag = text[start:index + 1]
                tags.add(tag)
                if replacer:
                    replaced_text += replacer(tag)
                else:
                    replaced_text += tag

    return tags, replaced_text

