def extend_cli(self, root_subparsers):
    parser = subparsers.add_parser('spec', help='Specify a file or directory')
    parser.add_argument('file_or_dir', help='The file or directory to specify')

def strip_root(path, root):
    if not path or not root:
        raise ValueError("Both 'path' and 'root' must be non-empty strings.")

    if not path.startswith(root):
        raise ValueError(f"The path '{path}' does not start with the root '{root}'.")

    return path[len(root):]
